// Validate and process global configuration
const config = $input.first().json;

// Validation functions
const validateUrl = (url) => {
  try {
    new URL(url);
    return true;
  } catch {
    return false;
  }
};

const validateApiKey = (key) => {
  return key && key.length > 10 && !key.includes('your_') && !key.includes('YOUR_');
};

const validateConfig = (configObj, configName) => {
  const errors = [];
  const warnings = [];

  switch (configName) {
    case 'youtube_config':
      if (!validateApiKey(configObj.access_token)) {
        errors.push('Invalid YouTube access token');
      }
      if (!configObj.client_id || !configObj.client_secret) {
        errors.push('Missing YouTube OAuth credentials');
      }
      if (!configObj.channel_id) {
        warnings.push('YouTube channel ID not set');
      }
      break;

    case 'ai_services_config':
      if (!validateApiKey(configObj.google?.api_key)) {
        warnings.push('Google API key not configured');
      }
      if (!validateApiKey(configObj.elevenlabs?.api_key)) {
        warnings.push('ElevenLabs API key not configured');
      }
      if (!validateApiKey(configObj.huggingface?.token)) {
        warnings.push('Hugging Face token not configured');
      }
      if (!validateApiKey(configObj.json2video?.api_key)) {
        warnings.push('JSON2Video API key not configured');
      }
      break;

    case 'notification_config':
      if (!validateUrl(configObj.discord?.webhook_url)) {
        warnings.push('Discord webhook URL not configured');
      }
      if (!configObj.telegram?.bot_token || !configObj.telegram?.chat_id) {
        warnings.push('Telegram configuration incomplete');
      }
      break;

    case 'gcp_config':
      if (!configObj.project_id) {
        errors.push('GCP Project ID is required');
      }
      if (!configObj.service_account_key) {
        errors.push('GCP Service Account Key is required');
      }
      break;
  }

  return { errors, warnings };
};

// Validate all configurations
const validationResults = {
  youtube: validateConfig(config.youtube_config, 'youtube_config'),
  ai_services: validateConfig(config.ai_services_config, 'ai_services_config'),
  media_services: validateConfig(config.media_services_config, 'media_services_config'),
  notifications: validateConfig(config.notification_config, 'notification_config'),
  gcp: validateConfig(config.gcp_config, 'gcp_config')
};

// Collect all errors and warnings
const allErrors = [];
const allWarnings = [];

Object.entries(validationResults).forEach(([service, result]) => {
  allErrors.push(...result.errors.map(error => `${service}: ${error}`));
  allWarnings.push(...result.warnings.map(warning => `${service}: ${warning}`));
});

// Determine configuration status
let status = 'healthy';
let statusMessage = 'All configurations are valid';

if (allErrors.length > 0) {
  status = 'error';
  statusMessage = `Configuration errors detected: ${allErrors.join(', ')}`;
} else if (allWarnings.length > 0) {
  status = 'warning';
  statusMessage = `Configuration warnings: ${allWarnings.join(', ')}`;
}

// Create service status summary
const serviceStatus = {
  youtube: {
    enabled: validateApiKey(config.youtube_config.access_token) && config.youtube_config.client_id,
    oauth_configured: !!(config.youtube_config.client_id && config.youtube_config.client_secret),
    channel_linked: !!config.youtube_config.channel_id
  },
  ai_services: {
    google: validateApiKey(config.ai_services_config.google?.api_key),
    elevenlabs: validateApiKey(config.ai_services_config.elevenlabs?.api_key),
    huggingface: validateApiKey(config.ai_services_config.huggingface?.token),
    json2video: validateApiKey(config.ai_services_config.json2video?.api_key)
  },
  media_services: {
    pixabay: validateApiKey(config.media_services_config.pixabay?.api_key),
    bitly: validateApiKey(config.media_services_config.bitly?.access_token)
  },
  notifications: {
    discord: validateUrl(config.notification_config.discord?.webhook_url),
    telegram: !!(config.notification_config.telegram?.bot_token && config.notification_config.telegram?.chat_id)
  },
  gcp: {
    project_configured: !!config.gcp_config.project_id,
    service_account_configured: !!config.gcp_config.service_account_key,
    secret_manager_enabled: config.gcp_config.secret_manager?.enabled
  }
};

// Calculate overall health score
const totalChecks = Object.values(serviceStatus).reduce((total, service) => {
  return total + Object.keys(service).length;
}, 0);

const passedChecks = Object.values(serviceStatus).reduce((total, service) => {
  return total + Object.values(service).filter(Boolean).length;
}, 0);

const healthScore = Math.round((passedChecks / totalChecks) * 100);

return {
  json: {
    // Configuration data
    ...config,

    // Validation results
    validation: {
      status: status,
      message: statusMessage,
      errors: allErrors,
      warnings: allWarnings,
      health_score: healthScore
    },

    // Service status
    service_status: serviceStatus,

    // Metadata
    config_version: '1.0.0',
    validated_at: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'production'
  }
};

